def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C' if history[0][1] == 'C' and history[1][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    last_my = my[-1]
    last_op = opp[-1]
    total_op_c = opp.count('C')
    total_op_d = n - total_op_c
    remaining = 100 - n

    # consecutive defections by opponent at end
    tail_def = 0
    for a in reversed(opp):
        if a == 'D':
            tail_def += 1
        else:
            break

    # consecutive cooperation at end
    tail_c = 0
    for a in reversed(opp):
        if a == 'C':
            tail_c += 1
        else:
            break

    recent_len = min(12, n)
    recent = opp[-recent_len:]
    recent_c = recent.count('C')
    recent_d = recent_len - recent_c

    # Detect opponent's likely strategy: if highly cooperative, exploit later.
    if total_op_d == 0:
        # Opponent always cooperated so far.
        if remaining <= 3:
            return 'D'
        if n >= 10 and tail_c >= 5:
            # occasional probe to gather points but maintain trust
            if n % 11 == 0:
                return 'D'
        return 'C'

    # If opponent almost always defects, defect to minimize losses.
    if total_op_d >= n - 1 or (recent_d == recent_len and recent_len >= 6):
        return 'D'

    # Opponent defected last round
    if last_op == 'D':
        if tail_def >= 2:
            # punish persistent defection
            if tail_def >= 4:
                return 'D'
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        # isolated defection
        if total_op_c >= n - 3 and n < 95:
            # forgive a rare defection from a generally cooperative opponent
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round
    if total_op_d * 2 > n:
        # opponent is more defective than cooperative
        if remaining <= 3:
            return 'D'
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Opponent fairly cooperative
    if remaining <= 1:
        return 'D'
    if remaining <= 4:
        if total_op_c >= n - 4:
            return 'D'
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # If we have been cooperating and opponent just cooperated, occasionally defect opportunistically
    if tail_c >= 4 and total_op_c >= n - 3:
        if n % 9 == 0:
            return 'D'
    if n % 17 == 0 and total_op_d > 0 and total_op_d < n // 4:
        return 'D'

    return 'C'
